def find_rectangles(grid):
    """Find rectangles made of single color (no defects)"""
    rows, cols = len(grid), len(grid[0])
    found = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited:
                continue
            if grid[r][c] in [0, 4, 8]:  # skip defects
                continue

            # Try to expand to form a rectangle
            color = grid[r][c]
            # Expand right
            ec, er = r, c
            while ec < rows and grid[ec][c] == color:
                er += 1
            er -= 1
            # Check if row c is all that color from c to any right point
            max_right = 1
            for rc in range(c+1, cols):
                all_color = True
                for rr in range(r, er+1):
                    if rr >= rows or grid[rr][rc] != color:
                        all_color = False
                        break
                if all_color:
                    max_right = rc + 1

            visited.add((r, c))
            found.append(((r, c, max_right)))

    return found

