def connected_components(grid):
    """Find connected components of each color (excluding defects)"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = defaultdict(list)  # color -> list of positions

    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited or grid[r][c] in [0, 4, 8]:
                continue
            color = grid[r][c]
            # BFS to find component
            comp = []
            queue = deque([(r, c)])
            visited.add((r, c))
            while queue:
                cr, cc = queue.popleft()
                comp.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            components[color].extend(comp)

    return components

