def get_weighted_maj(cls):
    rows, cols = len(cls), len(cls[0])
    weights = defaultdict(int)

    # Orthogonal neighbors get double weight
    for (dr, dc, val) in cls['ortho']:
        weights[val] += 2

    # Diagonal neighbors get single weight
    for (dr, dc, val) in cls['diag']:
        weights[val] += 1

    if not weights:
        return 1
    return max(weights.keys(), key=lambda x: weights[x])

def get_maj(cls):
    rows, cols = len(cls), len(cls[0])
    weights = defaultdict(int)

    for (dr, dc, val) in cls['ortho']:
        weights[val] += 1

    for (dr, dc, val) in cls['diag']:
        weights[val] += 1

    if not weights:
